def max_pieces(n, a, b):
    total_pieces = a + b
    if n == total_pieces:
        return 1
    elif n > total_pieces:
        return 0
    else:
        min_pieces = min(a, b)
        if min_pieces >= n:
            return 1
        else:
            return (total_pieces - n + min_pieces) // (n - min_pieces)

