def max_pieces_per_plate(n, a, b):
    total_pieces = a + b
    if total_pieces <= n:
        return 1
    elif a < n and b < n:
        return min(a // (n - a), b // (n - b))
    else:
        return min(a // (a + b - n), b // (a + b - n))

